package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.nio.file.attribute.FileTime;
import org.junit.jupiter.api.Test;

class SimpleVirtualBasicAttributesMutaGate1Test {

  @Test
  void creationTimeIsEpochForDirectoryAndRegularFile() {
    FileTime epoch = FileTime.fromMillis(0L);

    SimpleVirtualBasicAttributes dir = SimpleVirtualBasicAttributes.directory("d");
    assertNotNull(dir.creationTime());
    assertEquals(epoch, dir.creationTime());

    SimpleVirtualBasicAttributes file = SimpleVirtualBasicAttributes.regularFile("f", 5L);
    assertNotNull(file.creationTime());
    assertEquals(epoch, file.creationTime());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import org.junit.jupiter.api.Test;

class SimpleVirtualBasicAttributesMutaGate2Test {

  @Test
  void fileKeyReturnsEntryKeyForDirectoryAndRegularFile() {
    SimpleVirtualBasicAttributes dir = SimpleVirtualBasicAttributes.directory("dir/key");
    SimpleVirtualBasicAttributes file = SimpleVirtualBasicAttributes.regularFile("file/key", 42L);

    assertNotNull(dir.fileKey());
    assertNotNull(file.fileKey());
    assertEquals("dir/key", dir.fileKey());
    assertEquals("file/key", file.fileKey());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class SimpleVirtualBasicAttributesMutaGate3Test {

  @Test
  void isDirectoryReflectsEntryType() {
    SimpleVirtualBasicAttributes dir = SimpleVirtualBasicAttributes.directory("d");
    SimpleVirtualBasicAttributes file = SimpleVirtualBasicAttributes.regularFile("f", 5L);

    assertTrue(dir.isDirectory());
    assertFalse(file.isDirectory());
  }
}

